import{_ as o,o as t,c as r,ag as l}from"./chunks/framework.DzGOF12C.js";const g=JSON.parse('{"title":"Watermark GC 실험 — 시간축 보정 재검증","description":"","frontmatter":{},"headers":[{"level":2,"title":"시간 측정 방식 수정","slug":"시간-측정-방식-수정","link":"#시간-측정-방식-수정","children":[]},{"level":2,"title":"재검증 결과","slug":"재검증-결과","link":"#재검증-결과","children":[{"level":3,"title":"low=2, high=2 (베이스라인)","slug":"low-2-high-2-베이스라인","link":"#low-2-high-2-베이스라인","children":[]},{"level":3,"title":"low=134, high=2","slug":"low-134-high-2","link":"#low-134-high-2","children":[]},{"level":3,"title":"low=268, high=2","slug":"low-268-high-2","link":"#low-268-high-2","children":[]}]},{"level":2,"title":"결론","slug":"결론","link":"#결론","children":[]}],"relativePath":"computer/Research/URA/results/04 virt_watermark_GC 시간축 보정 재검증.md","filePath":"computer/Research/URA/results/04 virt_watermark_GC 시간축 보정 재검증.md"}'),a={name:"computer/Research/URA/results/04 virt_watermark_GC 시간축 보정 재검증.md"};function s(i,e,n,c,h,d){return t(),r("div",null,[...e[0]||(e[0]=[l('<h1 id="watermark-gc-실험-—-시간축-보정-재검증" tabindex="-1">Watermark GC 실험 — 시간축 보정 재검증 <a class="header-anchor" href="#watermark-gc-실험-—-시간축-보정-재검증" aria-label="Permalink to &quot;Watermark GC 실험 — 시간축 보정 재검증&quot;">​</a></h1><p><a href="./03 virt_watermark_GC (High-Low Watermark) 실험 결과.html">03번 보고서</a>에서 남겨뒀던 문제, &quot;<code>/proc/uptime</code>을 수동으로 찍어 계산한 시작 시각과 실제 dmesg GC 발생 시점 사이에 오차가 있었다&quot;는 이슈를 해결하고 재측정한 결과.</p><h2 id="시간-측정-방식-수정" tabindex="-1">시간 측정 방식 수정 <a class="header-anchor" href="#시간-측정-방식-수정" aria-label="Permalink to &quot;시간 측정 방식 수정&quot;">​</a></h2><p><strong>기존 방식(오차 있음)</strong>: 사람이 커맨드 실행 직전/직후에 <code>/proc/uptime</code>을 수동으로 찍어 <code>START_TIME</code> 계산 — 커맨드 입력 지연, 이전 실행 잔여 등으로 오차 발생.</p><p><strong>수정 방식</strong>: fio 실행 시 <code>--output-format=json</code>으로 받은 결과의 <code>job_start</code>(에폭 타임스탬프, ms 단위)를 시작 시각으로 사용. dmesg의 커널 타임스탬프(부팅 이후 초 단위)와는 별도 기준이므로, <code>uptime -s</code>(부팅 시각)와 조합해 둘을 같은 좌표계로 환산한 뒤 GC 로그의 발생 시점을 &quot;<code>seq_gc_invoke</code> 시작 이후 경과 시간(s)&quot;으로 정확히 계산.</p><p>이 보정 덕분에, 이전 보고서에서 그래프 x축이 실제 GC 발생 구간과 어긋나 보이던 문제가 해결되고, <strong>버스트가 정확히 몇 초 지점에서 얼마나 짧게 일어나는지</strong>까지 측정 가능해짐.</p><h2 id="재검증-결과" tabindex="-1">재검증 결과 <a class="header-anchor" href="#재검증-결과" aria-label="Permalink to &quot;재검증 결과&quot;">​</a></h2><h3 id="low-2-high-2-베이스라인" tabindex="-1">low=2, high=2 (베이스라인) <a class="header-anchor" href="#low-2-high-2-베이스라인" aria-label="Permalink to &quot;low=2, high=2 (베이스라인)&quot;">​</a></h3><p><code>gc_log_22.txt</code> 기준, GC가 약 32ms 간격으로 계속 1건씩 발생하며 <code>free_line_cnt</code>가 시종일관 2로 고정 — 이전 결과와 동일한 정상상태(steady state) 재확인.</p><p>![[GC_low2_freeLine_corrected_timing.png]]</p><h3 id="low-134-high-2" tabindex="-1">low=134, high=2 <a class="header-anchor" href="#low-134-high-2" aria-label="Permalink to &quot;low=134, high=2&quot;">​</a></h3><p><code>seq_gc_invoke</code> 시작 후 <strong>약 11.98초 지점</strong>과 <strong>약 16.26초 지점</strong>, 정확히 <strong>두 번</strong>의 burst가 관찰됨 — 03번 보고서에서 &quot;큰 latency 스파이크가 두 번 관찰됨&quot;이라고 추정했던 것을 정확한 시각으로 확인.</p><p>![[GC_low134_freeLine_corrected_timing.png]]</p><p>각 burst를 확대하면, <code>free_line_cnt</code>가 2에서 134까지 완전히 수직으로 튀어오르는 형태이며, 실제 소요 시간은 로그(<code>gc_log_1342.txt</code>) 기준 <strong>약 1.06ms</strong>(첫 GC~마지막 GC 타임스탬프 차이, <code>92614.414298</code> → <code>92614.415361</code>)에 불과함 — while 루프로 132회의 GC(<code>free=2</code>→<code>134</code>)가 사실상 한 순간에 몰아서 처리됨을 보여줌.</p><p><strong>burst 1 (약 11.98초 부근 확대)</strong><br> ![[GC_burst_zoom_low134_first.png]]</p><p><strong>burst 2 (약 16.26초 부근 확대)</strong><br> ![[GC_burst_zoom_low134_second.png]]</p><p>두 burst의 모양(기울기, 폭)이 거의 동일 — 동일한 조건(같은 워크로드 소모 속도, 같은 low/high 값)에서 반복적으로 같은 크기의 burst가 재현됨을 보여줌.</p><h3 id="low-268-high-2" tabindex="-1">low=268, high=2 <a class="header-anchor" href="#low-268-high-2" aria-label="Permalink to &quot;low=268, high=2&quot;">​</a></h3><p><code>gc_log_2682.txt</code> 기준, <strong>약 11.96초 지점</strong>에서 단 <strong>한 번</strong>의 burst만 관찰됨 — <code>free_line_cnt</code>가 2에서 268까지 수직으로 튀어오름. 소요 시간은 첫~마지막 GC 타임스탬프 차이(<code>93022.951305</code> → <code>93022.953352</code>) 기준 <strong>약 2.05ms</strong>로, low=134 burst보다 처리하는 line 수(267개)가 약 2배 많은 만큼 소요 시간도 거의 비례해서 늘어남.</p><p>![[GC_low268_freeLine_corrected_timing.png]]</p><p><strong>burst 확대</strong><br> ![[GC_burst_zoom_low268.png]]</p><h2 id="결론" tabindex="-1">결론 <a class="header-anchor" href="#결론" aria-label="Permalink to &quot;결론&quot;">​</a></h2><ul><li>시간축 보정 후에도 03번 보고서의 정성적 결론(low가 낮을수록 자주·작게, 높을수록 드물게·크게 몰아침)은 그대로 재확인됨 — 이번 보정으로 얻은 것은 <strong>정확한 발생 시각과 burst 소요 시간</strong>이라는 정량적 디테일.</li><li><strong>burst 소요 시간이 매우 짧음(ms 단위)</strong>: while 루프가 중간에 다른 작업 없이 GC만 연속으로 처리하기 때문 — 처리해야 할 line 수(132개 vs 267개)에 거의 비례해서 burst 폭이 늘어남 (line당 처리 시간이 거의 일정, 약 8μs/line 수준으로 두 케이스에서 일관됨: 1.06ms/132 ≈ 8.0μs, 2.05ms/267 ≈ 7.7μs).</li><li>low=134에서 burst가 <strong>정확히 두 번, 거의 동일한 간격·모양으로 재현</strong>된다는 것은, opportunistic GC 없이 순수하게 워크로드의 쓰기 속도만으로 free_line이 소진되는 주기가 일정하다는 것을 시사함 — 다음 실험에서는 이 burst 간격(약 4.3초)이 <code>--bs</code>나 <code>--size</code>를 바꿨을 때 어떻게 변하는지 확인해볼 수 있음.</li></ul>',23)])])}const u=o(a,[["render",s]]);export{g as __pageData,u as default};
